def group_anagrams(words):
    anagram_groups = {}
    for word in words:
        key = ''.join(sorted(word.lower()))
        if key not in anagram_groups:
            anagram_groups[key] = []
        anagram_groups[key].append(word)
    return [list(group) for group in anagram_groups.values()]
